if not isinstance(name, str):
    return False
return _normalized_regex.fullmatch(name) is not None

if filename.endswith(".tar.gz"):
    file_stem = filename[: -len(".tar.gz")]
elif filename.endswith(".tgz"):
    file_stem = filename[: -len(".tgz")]
elif filename.endswith(".zip"):
    file_stem = filename[: -len(".zip")]
else:
    raise InvalidSdistFilename(
        f"Invalid sdist filename (extension must be '.tar.gz', '.tgz', or '.zip'):"
        f" {filename!r}"
    )

# We are requiring a PEP 440 version, which cannot contain dashes,
# so we split on the last dash.
name_part, sep, version_part = file_stem.rpartition("-")
if not sep:
    raise InvalidSdistFilename(f"Invalid sdist filename: {filename!r}")
if not name_part:
    raise InvalidSdistFilename(
        f"Invalid sdist filename (empty project name): {filename!r}"
    )

name = canonicalize_name(name_part)

try:
    version = Version(version_part)
except InvalidVersion as e:
    raise InvalidSdistFilename(
        f"Invalid sdist filename (invalid version): {filename!r}"
    ) from e

return (name, version)

if (typeof string !== 'string') {
	throw new TypeError('Expected a string');
}

// Escape characters with special meaning either inside or outside character sets.
// Use hexadecimal escapes where Unicode patterns' stricter grammar disallows simpler forms.
return string
	.replace(/[|\\{}()[\]^$+*?.]/g, '\\$&')
	.replace(/-/g, '\\x2d')
	.replace(/\//g, '\\x2f');

const node = new Node(value);

if (this.#head) {
	this.#tail.next = node;
	this.#tail = node;
} else {
	this.#head = node;
	this.#tail = node;
}

this.#size++;
return this.#size;

const limit = arguments.length === 0 ? Infinity : arguments[0];
let count = 0;

while (this.#head && count < limit) {
	yield this.dequeue();
	count++;
}

if (!this.#head) {
	return null;
}

return this.#head.value;

